  interior: { en: "Interior design & contracting", ar: "تصميم داخلي ومقاولات",
    hide: ["rentals", "shop", "stock", "assets", "accounting.loans", "accounting.bankrec", "accounting.recurring", "accounting.budgets", "purchasing.orders"] },
