// unread mark: only what this person has not seen in the bell yet (seen and ignored are kept per person)
function bellBadge(n) { ["#bellc", "#bellc2"].forEach(id => { const b = $(id); if (b) { b.hidden = !n; b.textContent = n > 9 ? "9+" : n; } }); }
