async function applyAppIcon() {
  if (!S.boot || !S.boot.settings) return;
  const k = appIconKey(), src = appIconSrc(k); if (_iconApplied === src) return; _iconApplied = src;
  try {
    const fav = $("#appicon"); if (fav) fav.href = await iconPng(src, 64);
    let at = document.querySelector("link[rel=apple-touch-icon]"); if (at) at.href = k === "beyond" ? "apple-touch-icon.png" : await iconPng(src, 180, true);
    const man = document.querySelector("link[rel=manifest]");
    // the built-in icons have real manifest files on the site, so Android installs a proper app with that icon
    // (a manifest made in the page cannot be packaged: Android would show Chrome's badge on the home-screen icon)
    // the default icon keeps the page's own manifest (both files are identical): swapping the link on every load made
    // Chrome think the installed app had changed and show "App update available" in the title bar
    if (man && k === "beyond") return;
    if (man && APP_ICONS.some(x => x[0] === k)) { man.href = `manifest-${k}.webmanifest`; return; }
    if (man) { const base = new URL("./", location.href).href;
      const m = { name: appName(), short_name: appName(), start_url: base, scope: base, display: "standalone", background_color: "#05061a", theme_color: "#05061a",
        icons: [{ src: await iconPng(src, 192), sizes: "192x192", type: "image/png" }, { src: await iconPng(src, 512), sizes: "512x512", type: "image/png" },
          { src: await iconPng(src, 512, true), sizes: "512x512", type: "image/png", purpose: "maskable" }] };
      man.href = URL.createObjectURL(new Blob([JSON.stringify(m)], { type: "application/manifest+json" })); }
  } catch { /* the default icon stays */ }
}
// Sidebar header: logo and/or name (Settings → Appearance → Sidebar shows), and an optional tagline
function brandBlock(st) {
  const ap = platformOwner() ? (st.appearance || {}) : {}, show = ap.brand_show || "logo", src = brandLogoSrc();
  const logo = src && show !== "name" ? `<img class="brand-logo ${show === "logo" ? "only" : ""}" src="${esc(src)}" alt="${esc(appName())}">` : "";
  const name = show !== "logo" || !logo ? `<b>${esc(appName())}</b>` : "";
  const tag = ap.tagline_show === false || show === "logo" ? "" : (ap.tagline != null ? ap.tagline : st.company_tagline || "");
  // each part (logo, name, tagline) has its own position and size; a blank position follows the logo's
  const pos = v => (["left", "center", "right"].includes(v) ? v : ""), px = (v, lo, hi) => (+v ? Math.min(hi, Math.max(lo, +v)) : 0);
  const la = pos(ap.brand_align), na = pos(ap.brand_name_align) || la, ta = pos(ap.brand_tag_align) || la;
  const ls = px(ap.brand_logo_size, 24, 220), ns = px(ap.brand_name_size, 10, 40), ts = px(ap.brand_tag_size, 8, 28);
  const css = (a, size) => (a ? `text-align:${a};` : "") + (size ? `font-size:${size}px;` : "");
  const logoHtml = logo && (la || ls) ? `<span class="brand-logo-row" style="${la ? `text-align:${la};` : ""}${ls ? `--brand-logo:${ls}px;` : ""}">${logo}</span>` : logo;
  const nameHtml = name && (na || ns) ? name.replace("<b>", `<b style="${css(na, ns)}">`) : name;
  const tagHtml = tag ? `<small${ta || ts ? ` style="display:block;${css(ta, ts)}"` : ""}>${esc(tag)}</small>` : "";
  return `<a href="#/dashboard" class="brand ${show === "logo" && logo ? "logo-only" : ""}" title="${esc(t("m_dashboard"))}">${logoHtml}${nameHtml}${tagHtml}</a>`;
}
// Every possible "+ New" item with its label and whether this user may use it
function newMenuItems() {
  const defs = Object.fromEntries((S.boot.enums.menu_items || []).map(m => [m.key, m]));
  const types = Object.fromEntries((S.boot.enums.entry_types || []).map(e => [e.id, e]));
  const docLabel = { direct_cost: "m_costs", expense: "m_expenses", payment: "m_payments", receipt: "m_receipts", invoice: "m_invoices", payroll: "m_payroll", stock_move: "m_moves", journal: "m_journal", bu: "m_bus", offer: "m_offers" };
  return (S.boot.enums.new_menu || []).map(({ key, show }) => {
    if (key.startsWith("entry:")) { const e = types[key.slice(6)]; if (!e) return null;
      return { key, show: show && e.active !== false, label: (S.lang === "ar" && e.name_ar) || e.name, ok: can("accounting.journal", "add") && shown("accounting.journal"), entry: true }; }
    const d = defs[key]; if (!d) return null;
    const doc = key.startsWith("doc:") ? key.slice(4) : null;
    return { key, show, label: doc ? t(docLabel[doc]) : (S.lang === "ar" ? d.ar : d.en), ok: can(d.module, "add") && shown(d.module) };
  }).filter(Boolean);
}
