const phoneMenuSelect = (attrs) => `<label class="f">${esc(L2("Menu on phones", "القائمة على الهاتف"))}<select ${attrs}>${[["overlay", L2("Overlay (default)", "فوق الشاشة (افتراضي)")], ["rail", L2("Icon strip", "شريط أيقونات")]].map(([v, l]) => `<option value="${v}" ${phoneMenu() === v ? "selected" : ""}>${esc(l)}</option>`).join("")}</select></label>`;
const hoverNav = () => navMode() === "hover" && matchMedia("(hover:hover) and (pointer:fine)").matches;
document.addEventListener("click", e => { if (!e.target.closest(".grp-wrap.fly")) $$(".grp-wrap.fly").forEach(x => x.classList.remove("fly")); });
function renderNav(active) {
  const nav = $("#nav"); if (!nav) return;
  let html = "", title = "", group = "";
  const open = new Set(store.get("navOpen", "").split(",").filter(Boolean));
  const parent = { bu: "bus", invoice: "invoices", boq: "boqs", offer: "offers", offertypes: "offers", loan: "loans", cust: "custody",
    rental: "rentals", product: "products", sale: "sales", bankstmt: "bankrec", extract: "extracts" }[active.split("/")[0]];
  const em = effectiveMenu(), full = location.hash.replace(/^#\//, "");
  const exactCopy = em.some(([, items]) => items.some(i => i[4] && i[1] === full));   // a copy with these exact filters is the one lit
  for (const [g, items] of em) {
    const vis = items.filter(i => can(i[2]) && shown(i[2]));
    if (!vis.length) continue;
    let links = "", has = false;
    for (const it of vis) {
      const [k, r] = it, base = r.split("?")[0], name = itemLabel(it);
      const on = it[4] ? r === full : !exactCopy && (active === base || active.startsWith(base + "/") || parent === base);
      if (on) { title = name; group = groupLabel(g); has = true; }
      const lk = (ML().lock || []).includes(k) ? " locked" : "";
      links += g === "g_home" ? `<a href="#/${r}" data-k="${esc(k)}" class="${on ? "on" : ""}${lk}" title="${esc(name)}">${svg(ROUTE_IC[base] || GROUP_IC[g])}<span>${esc(name)}</span></a>`
        : `<a href="#/${r}" data-k="${esc(k)}" class="${on ? "on" : ""}${lk}"><i class="dash"></i><span>${esc(name)}</span></a>`;
    }
    if (g === "g_home") { html += `<div class="grp-solo">${links}</div>`; continue; }
    html += `<div class="grp-wrap ${!hoverNav() && (has || open.has(g)) ? "open" : ""} ${has ? "has" : ""}"><button class="grp${(ML().lock || []).includes("g:" + g) ? " locked" : ""}" data-a="grp" data-g="${g}" title="${esc(groupLabel(g))}">${svg(GROUP_IC[g] || "grid")}<span>${esc(groupLabel(g))}</span>${svg("chev", "chev")}</button><div class="grp-items"><div class="grp-in"><div class="fly-t">${esc(t(g))}</div>${links}</div></div></div>`;
  }
  nav.innerHTML = html;
  const offMenu = { "my-day": L2("Attendance", "الحضور"), profile: L2("My profile", "ملفي الشخصي"), notifications: L2("Notifications", "الإشعارات") }[active.split("/")[0]];
  $("#ttl").textContent = title || offMenu || t("m_dashboard");
  $("#crumb").textContent = group;
  // detail pages (a business unit, an invoice, a quotation, an offer…) get a back arrow to the list they came from
  const inMenu = effectiveMenu().some(([, items]) => items.some(i => i[1].split("?")[0] === active));
  const back = $(".top-back"); if (back) back.style.display = inMenu ? "none" : "";
  $$(".bottombar .bb-home").forEach(a => a.classList.toggle("on", active === "dashboard"));
  loadAlerts();
}

