      cfg.note = v.note; cfg.from = v.from; cfg.to = v.to; cfg.slot = +v.slot || 30; cfg.per_slot = +v.per_slot || 1; cfg.ahead = +v.ahead || 30; cfg.notice_hours = +v.notice_hours || 0; cfg.place = v.place; cfg.show_prices = !!v.show_prices;
