    if (el.classList.contains("pscr")) { const m = el.dataset.pk.split(".")[0]; const vals = (subs[m] || []).map(s => ($(`input[name=pp_${m}_${s}]:checked`, f) || {}).value);
      $$(`input[name=ps_${m}]`, f).forEach(r => { r.checked = vals.every(v => v === vals[0]) && r.value === vals[0]; }); }
