// ================================================== help & support
// Where reports go. E-mail stays empty until the domain's support address exists (the button says "coming soon").
const SUPPORT = { whatsapp: "201012884176", email: "" };
const SUP_KINDS = () => [["bug", L2("Problem", "مشكلة")], ["question", L2("Question", "سؤال")],
  ["suggestion", L2("Suggestion", "اقتراح")], ["billing", L2("Subscription and billing", "الاشتراك والفوترة")]];
const SUP_STATUS = () => ({ sent: L2("Sent", "مُرسل"), answered: L2("Answered", "تم الرد"), solved: L2("Resolved", "تم الحل") });
const supEdition = () => STATIC ? (cloudOn() ? L2("Online (shared workspace)", "متصل (مساحة عمل مشتركة)") : L2("Browser (this device only)", "المتصفح (هذا الجهاز فقط)"))
  : (cloudOn() ? L2("Desktop with shared workspace", "سطح المكتب مع مساحة عمل مشتركة") : L2("Desktop (offline)", "سطح المكتب (دون اتصال)"));
// the diagnostics go to support as they are; on screen their names are in the reader's language
const SUP_DIAG_L = () => ({ version: L2("Version", "الإصدار"), edition: L2("Edition", "النسخة"), company: L2("Company", "الشركة"), user: L2("User", "المستخدم"),
  role: L2("Role", "الدور"), screen: L2("Screen", "الشاشة"), language: L2("Language", "اللغة"), browser: L2("Browser", "المتصفح"),
  display: L2("Display", "الشاشة (المقاس)"), online: L2("Online", "متصل بالإنترنت"), errors: L2("Recent errors", "آخر الأخطاء") });
function supDiag() {
  const u = S.boot.user || {}, st = S.boot.settings || {};
  return { version: S.boot.version || "", edition: supEdition(), company: st.company_name || "", user: u.username || "",
    role: u.is_super ? L2("Super administrator", "مسؤول أعلى") : u.is_admin ? L2("Administrator", "مسؤول") : L2("User", "مستخدم"), screen: (S.lastPage || "").slice(0, 120), language: S.lang,
    browser: navigator.userAgent.slice(0, 200), display: `${innerWidth}×${innerHeight} @${devicePixelRatio || 1}x`,
    online: navigator.onLine ? L2("Yes", "نعم") : L2("No", "لا"), errors: RECENT_ERRS.slice(-5).join(" | ") || "—" };
}
const supText = (t, withDiag) => {
  const kind = (SUP_KINDS().find(k => k[0] === t.kind) || [])[1] || t.kind;
  const lines = [`BeyondERP support — ${t.ref}`, `${kind}: ${t.subject}`];
  if (t.body) lines.push("", t.body);
  if (withDiag && t.diag && Object.keys(t.diag).length) lines.push("", "— Technical details —", ...Object.entries(t.diag).filter(([, v]) => v).map(([k, v]) => `${k}: ${v}`));
  return lines.join("\n").slice(0, 1800);
};
const supSend = (t, channel, withDiag) => {
  const msg = supText(t, withDiag);
  if (channel === "whatsapp") window.open(`https://wa.me/${SUPPORT.whatsapp}?text=${encodeURIComponent(msg)}`, "_blank", "noopener");
  else if (channel === "email") location.href = `mailto:${SUPPORT.email}?subject=${encodeURIComponent(`[${t.ref}] ${t.subject}`)}&body=${encodeURIComponent(msg)}`;
  else navigator.clipboard.writeText(msg).then(() => toast(L2("Copied. Paste it into your message to us.", "تم النسخ. الصقه في رسالتك إلينا.")), () => uiAlert(msg));
};
