  const items = (em.find(([gg]) => gg === g) || [, []])[1], idx = items.findIndex(i => i[0] === k), it = items[idx] || [];
  const copy = it[4], here = parseHash(), hereRoute = here.parts.join("/"), withFilters = location.hash.replace(/^#\//, "");
  const out = [{ ic: "↗", label: L2("Open", "فتح"), act: () => { location.hash = "#/" + route; } },
    { ic: "⧉", label: L2("Open in a tab inside BeyondERP", "فتح في تبويب داخل BeyondERP"), act: () => tabOpen("#/" + route) },
    { ic: "↗", label: L2("Open in a new browser tab", "فتح في تبويب متصفح جديد"), act: () => open(location.pathname + "#/" + route, "_blank") },
    { ic: "🔗", label: L2("Copy link", "نسخ الرابط"), act: () => copyText(location.origin + location.pathname + "#/" + route) }];
  if (!canMenus()) return out.concat({ note: L2("Renaming and arranging the menu requires the “Arrange menus and forms” permission, granted by an administrator.", "تتطلب إعادة تسمية القائمة وترتيبها صلاحية «ترتيب القوائم والنماذج» التي يمنحها المسؤول.") });
  const L0 = ML(), ownLock = (L0.lock || []).includes(k);
  if (navLockedK(k)) return out.concat({ sep: 1 }, ownLock && !L0.lockAll
    ? { ic: "🔓", label: L2("Unlock", "إلغاء القفل"), act: () => lockToggle(k, false) }
    : { note: L0.lockAll ? L2("The entire menu is locked. Unlock it from a section's right-click menu.", "القائمة كلها مقفلة. ألغِ القفل من قائمة الزر الأيمن لأي قسم.")
                         : L2("The section is locked. Unlock the section to make changes.", "القسم مقفل. ألغِ قفل القسم لإجراء التعديلات.") });
  const moveTo = gg => saveLayout(L => { if (copy) { const c = (L.copies || []).find(x => x.k === k); if (c) c.g = gg; } else { L.move = L.move || {}; L.move[k] = gg; } });
  const reorder = d => saveLayout(L => { L.order = L.order || {}; const keys = items.map(i => i[0]); const j = idx + d; if (j < 0 || j >= keys.length) return;
    [keys[idx], keys[j]] = [keys[j], keys[idx]]; L.order[g] = keys; });
  const dup = (r, name) => saveLayout(L => { L.copies = L.copies || []; const ck = "c_" + Date.now().toString(36);
    L.copies.push({ k: ck, of: copy ? copy.of : k, route: r, g, label: { [S.lang]: name } });
    L.order = L.order || {}; const keys = items.map(i => i[0]); keys.splice(idx + 1, 0, ck); L.order[g] = keys; });
  out.push({ sep: 1 },
    { ic: "✎", label: L2("Rename", "إعادة تسمية"), act: async () => { const v = await uiPrompt(L2("New name (blank: original)", "الاسم الجديد (فارغ: الأصلي)"), itemLabel(it)); if (v === null) return;
      if (copy) saveLayout(L => { const c = (L.copies || []).find(x => x.k === k); if (c) c.label = { ...c.label, [S.lang]: v.trim() || c.label[S.lang] }; }); else saveMenuLabel(k, v.trim()); } },
    { ic: "⇄", label: L2("Move to section", "نقل إلى قسم"), sub: () => em.filter(([gg]) => gg !== "g_home" && (gg === g || !navLockedG(gg))).map(([gg]) => ({ label: groupLabel(gg), on: gg === g, act: () => gg !== g && moveTo(gg) }))
      .concat({ sep: 1 }, { ic: "＋", label: L2("New section", "قسم جديد"), act: async () => { const name = await uiPrompt(L2("New section name", "اسم القسم الجديد"), ""); if (!name || !name.trim()) return;
        const gk = "cg_" + Date.now().toString(36); await saveLayout(L => { L.groups = L.groups || []; L.groups.push({ k: gk, label: { [S.lang]: name.trim() } });
          if (copy) { const c = (L.copies || []).find(x => x.k === k); if (c) c.g = gk; } else { L.move = L.move || {}; L.move[k] = gk; } }); } }) },
    { ic: "↑", label: L2("Move up", "تحريك لأعلى"), dis: idx <= 0, act: () => reorder(-1) },
    { ic: "↓", label: L2("Move down", "تحريك لأسفل"), dis: idx >= items.length - 1, act: () => reorder(1) },
    { ic: "⧉", label: L2("Duplicate", "تكرار"), act: async () => { const v = await uiPrompt(L2("Copy name", "اسم النسخة"), itemLabel(it) + " 2"); if (v && v.trim()) dup(route, v.trim()); } });
